        bool fresh=false;
        for(int i=0;i<(int)stamp.size();++i)if(text[start+i]!='*'){
            if(text[start+i]!=stamp[i])return false;
            fresh=true;
        }
        return fresh;
    }
    int erase(string& text,int start,int length){
        int count=0;
        for(int i=0;i<length;++i)if(text[start+i]!='*'){
            text[start+i]='*';
            ++count;
        }
        return count;
    }
